 * Rendered into every v2 authoring/repair prompt.
 */
export const DISCIPLINE_SENTENCE =
  'Acceptors must guard against invalid proposals (an action that the\n' +
  'implementation does not act on in the current state must be a no-op via\n' +
  '`reject(reason)`, NOT a throw)';

/** Indent a multi-line renderer snippet. */
const indent = (snippet, pad = '    ') => snippet.split('\n').map((l) => pad + l).join('\n');

/** The v2 export-surface line, shared by every v2 builder. */
const V2_EXPORTS = 'module.exports = { instance, init, actions, getState, setState };';

/** The shared v2 module-contract block (author + repair prompts). */
function v2ModuleContract(contract) {
  return `You MUST export exactly this shape:

    ${V2_EXPORTS}

- \`instance\` — the SAM instance, created with:
  \`const instance = createInstance({ strict: true, hasAsyncActions: false });\`
  (\`strict: true\` and \`hasAsyncActions: false\` are REQUIRED)
- Component declaration (v2 strict form):
  - \`modelShape\` — declare EXACTLY the observable keys:

${indent(renderModelShape(contract))}

    Copy this modelShape EXACTLY. A key rendered with a type ARRAY
    (\`{ type: ['string', 'object'] }\`) is a UNION — every listed arm is
    legal; do NOT collapse the array to a single type (the strict checker
    throws on the other arm), and never widen a single-typed key.

  - \`actions\` — an OBJECT keyed by the action names. Each entry is the full
    form \`{ action, schema, domain }\` with \`action: (data = {}) => ({ ...data })\`
    (the proposal is the data payload). Use EXACTLY these payload schemas:

${indent(renderIntentSchemas(contract))}

    and EXACTLY these input domains (payload objects, one per entry — this is
    the pinned exploration domain; the model checker fires these intents in
    all combinations from the initial state, so the code must behave safely
    for EVERY payload below in ANY state it can reach):

${indent(renderIntentDomains(contract))}

  - \`acceptors\` — an OBJECT keyed by the same action names (the framework
    binds proposals to acceptors; do NOT write flag guards or a dispatch
    switch). Each acceptor is
    \`(model) => (proposal, { reject, next, unchanged }) => { ... }\` — a
    NEXT-STATE relation (sam-pattern 2.1 prime semantics): \`model\` is the
    FROZEN pre-state (read-only; writing \`model.x\` throws \`SamShapeError\`),
    and every write goes to the \`next\` draft.
  - COMMIT RULE (next-state form): for a FLAT state key, assign
    \`next.someKey = value\` — the right-hand side reads the PRE-state
    (\`next.count = model.count + 1\`). For a state key holding a NESTED
    map/object, assign the key WHOLE:
    \`next.<key> = { ...model.<key>, [k]: updated };\` — do NOT mutate
    \`model.<key>[k].field\` or \`next.<key>[k].field\` in place.
  - FRAME RULE: on every ACCEPTED path, every declared modelShape key must be
    either assigned via \`next.<key> = …\` or explicitly named unchanged:
    \`unchanged('keyA', 'keyB')\` — otherwise the step throws \`SamFrameError\`.
    A rejected step (\`return reject(reason)\`) needs NO framing. Never assign
    the same key twice in one step, and never read a value back from \`next\` —
    thread computed values through local consts.
  - WIRING — register everything with EXACTLY this idiom (the component
    members MUST be nested under the \`component\` key of a SINGLE
    \`instance({...})\` call; \`instance(component)\` or top-level members
    register NOTHING and the module fails validate()):

        const control = instance({
          initialState: { ...INITIAL_STATE },
          component: { modelShape, actions, acceptors, reactors: [] },
        });
        const { intents } = control;
- \`init()\` — resets to the initial state: EXACTLY \`setState(INITIAL_STATE)\`
  and nothing else. Do NOT call \`instance({}).state()\` anywhere —
  \`getState()\` is the safe snapshot accessor (a model data key like 'state'
  returns data, not the method; sam-lib #29).
- \`getState()\` — \`instance({}).getState()\`.
- \`setState(snapshot)\` — \`instance({}).setState(snapshot)\`.
- \`actions\` (export) — the named intents:
  \`{ ACTION: (data = {}) => intents.ACTION(data), ... }\`.

The initial state is:

    ${renderInitState(contract)}

## DETERMINISM RULES (violations are detected and fail the verification)

- No I/O, no timers, no Date/clock access, no Math.random, no async actions
- ${DISCIPLINE_SENTENCE.split('\n').join('\n  ')}
- No hidden state: every piece of state lives under the declared modelShape keys
- Do NOT include component \`safety\` conditions or a \`render\` function —
  invariants are verified in a separate phase
- The component MUST be anonymous: never set a \`name:\` key on it. A named
  component binds its acceptors to a LOCAL component state tree, so every
  guard reads undefined and the machine is dead at init (this is gated and
  will fail the build)`;
}

/** Render optional replay/determinism triage evidence for a repair prompt. */
function renderTriage(triage) {
  if (!triage) return '';
  const L = [];
  if (triage.nondeterministic) {
    L.push(`## Determinism flag

Two identical explorations of this module produced DIFFERENT state graphs —
the code is nondeterministic (Math.random / Date.now / retained mutable module
state). Remove the nondeterminism; every transition must depend only on
(state, action, data).`);
  }
  const replay = Array.isArray(triage.replay) ? triage.replay : [];
  if (replay.length) {
    const rows = replay.map((r) => {
      const whereBits = [r.scenario, r.index !== undefined ? `#${r.index}` : null].filter((x) => x !== null && x !== undefined && x !== '');
      const where = whereBits.length ? ` (${whereBits.join(' ')})` : '';
      const cls = r.classification ? ` classified '${r.classification}'` : '';
      const reason = r.rejectionReason !== undefined ? ` reason: ${JSON.stringify(r.rejectionReason)}` : '';
      const err = r.error ? ` error: ${r.error}` : '';
      return `- ${r.action}${where}: status ${r.status || 'fail'}${cls}${reason}${err}`;
    });
    L.push(`## Trace-replay triage (sam-tv classification of the failing windows)

'rejected' and 'identity-by-mutation' are the two GOOD no-op classes;
'unhandled' means the acceptor neither acted nor rejected — add an explicit
\`reject(reason)\` guard for that case. A 'rejected' window that still fails
disagrees with the trace: the guard fires when the implementation would act.

${rows.join('\n')}`);
  }
  return L.length ? `\n${L.join('\n\n')}\n` : '';
}

/** Stage 0: draft a contract.json from a free-form feature description. */
export function buildContractDraftPrompt(intent, { lang = 'javascript' } = {}) {
  return `You are drafting a Polygraph verification contract for a NEW piece of
stateful ${lang} code, before any of it is written. The contract is the design
spec: observable state, the action alphabet, and the rules a reader would need
to reproduce the behavior.

content.content:
1	// Shared contract -> prompt-text renderers. ONE source of truth for how a
2	// contract's state keys / init state / action alphabet are shown to a model,
3	// so build_prompt.mjs (audit mode) and polygen_prompts.mjs (author mode)
4	// never drift into describing the same contract differently.
5	import { dataFieldsOf, stable } from './load-spec.mjs';
6	
7	/** Render the observable-state key list from the contract. */
8	export function renderStateKeys(contract) {
9	  return contract.stateKeys
10	    .map((k) => {
11	      const name = typeof k === 'string' ? k : k.name;
12	      const type = typeof k === 'string' ? '' : (k.type ? ` — ${k.type}` : '');
13	      return `  - \`${name}\`${type}`;
14	    })
15	    .join('\n');
16	}
17	
18	/** Render the initial-state object literal. */
19	export function renderInitState(contract) {
20	  if (contract.initState) return JSON.stringify(contract.initState);
21	  // Fall back to a null-filled object over the declared keys.
22	  const obj = {};
23	  for (const k of contract.stateKeys) obj[typeof k === 'string' ? k : k.name] = null;
24	  return JSON.stringify(obj);
25	}
26	
27	/** Render the action alphabet with data shapes. */
28	export function renderActions(contract) {
29	  return Object.entries(contract.actions)
30	    .map(([name, spec]) => {
31	      const fields = dataFieldsOf(spec);
32	      const shape =
33	        fields && Object.keys(fields).length
34	          ? `{ ${Object.entries(fields).map(([f, t]) => `${f}: ${t}`).join(', ')} }`
35	          : '{ }';
36	      return `          '${name}'  data: ${shape}`;
37	    })
38	    .join('\n');
39	}
40	
41	/** Render specialRules as a bullet list, or a one-line "none declared". */
42	export function renderSpecialRules(contract) {
43	  const rules = contract.specialRules || [];
44	  if (!rules.length) return '  (none declared)';
45	  return rules
46	    .map((r) => {
47	      const where = [r.whenState ? `state=${r.whenState}` : null, r.whenAction ? `action=${r.whenAction}` : null]
48	        .filter(Boolean)
49	        .join(', ');
50	      return `  - **${r.name}**${where ? ` (${where})` : ''}: ${r.note || ''}`;
51	    })
52	    .join('\n');
53	}
54	
55	/** Render terminalStates as a bullet list, or a one-line "none declared". */
56	export function renderTerminalStates(contract) {
57	  const terms = contract.terminalStates || [];
58	  return terms.length ? terms.map((t) => `  - \`${t}\``).join('\n') : '  (none declared)';
59	}
60	
61	// ── v2 (SAM strict-profile) renderers ───────────────────────────────────────
62	// These derive the v2 module declarations — modelShape, per-intent schema,
63	// per-intent domain, named rejections — from the SAME contract fields the
64	// legacy renderers above read. No schema change: stateKeys/initState feed
65	// modelShape, actions[].dataFields feed intent schemas, dataDomain feeds
66	// intent domains, specialRules feed reject(reason) requirements. The legacy
67	// renderers above are still used: the v2 template renders {state_keys},
68	// {init_state} and {action_alphabet} from them.
69	
70	const V2_TYPES = ['string', 'number', 'boolean', 'object', 'array'];
71	
72	/** Infer a v2 schema/shape type from a concrete JS value; null when unknowable. */
73	function typeOfValue(v) {
74	  if (v === null || v === undefined) return null;
75	  if (Array.isArray(v)) return 'array';
76	  const t = typeof v;
77	  return V2_TYPES.includes(t) ? t : null;
78	}
79	
80	/** Infer a v2 type from a human-readable type note (e.g. "number — coins"). */
81	function typeOfNote(note) {
82	  if (!note || typeof note !== 'string') return null;
83	  const n = note.toLowerCase();
84	  if (/\bnumber\b|\bint(eger)?\b|\bfloat\b/.test(n)) return 'number';
85	  if (/\bbool(ean)?\b/.test(n)) return 'boolean';
86	  if (/\barray\b|\blist\b|\[\]/.test(n)) return 'array';
87	  if (/\bobject\b|\bmap\b|\brecord\b|\bdict\b/.test(n)) return 'object';
88	  if (/\bstring\b|'[^']*'|"[^"]*"/.test(n)) return 'string';
89	  return null;
90	}
91	
92	/**
93	 * Classify one union arm as a runtime type — PURE type tokens only. An arm
94	 * that is prose ("array of enum: 'pending'", "3-letter code", "nullable
95	 * string") returns null and contributes NOTHING: a note-derived union is
96	 * only believed when the arms are unambiguous type expressions, because a
97	 * false union silently strips shape checking from a single-runtime-type key
98	 * (review finding: the polygraph-oms-go contract's "array of enum: 'a' |
99	 * 'b'" note split into a bogus array|string union — the container prefix
100	 * rides only on the first arm while every later enum member classifies
101	 * standalone).
102	 */
103	function runtimeTypeOfArm(arm) {
104	  if (/^'[^']*'$/.test(arm) || /^"[^"]*"$/.test(arm)) return 'string';
105	  if (/^-?\d+(\.\d+)?$/.test(arm)) return 'number';
106	  if (/^(true|false)$/.test(arm)) return 'boolean';
107	  if (/^\{.*\}$/.test(arm)) return 'object';
108	  if (/^\[.*\]$/.test(arm) || /^[A-Za-z_$][\w<>,.\s]*\[\]$/.test(arm) || /^Array\s*<.*>$/.test(arm)) return 'array';
109	  if (/^(Record|Map)\s*<.*>$/.test(arm)) return 'object';
110	  if (/^(string|str)$/i.test(arm)) return 'string';
111	  if (/^(number|int|integer|float)$/i.test(arm)) return 'number';
112	  if (/^(bool|boolean)$/i.test(arm)) return 'boolean';
113	  if (/^object$/i.test(arm)) return 'object';
114	  if (/^array$/i.test(arm)) return 'array';
115	  return null;
116	}
117	
118	/**
119	 * Split a type note on TOP-LEVEL '|' (respecting quotes/braces/brackets) and
120	 * classify each arm. "'LOCKED' | 'UNLOCKED'" is two string literals — one
121	 * runtime type; "string | {red: string}" is two runtime types. Returns
122	 * { types: sorted distinct runtime types (prose arms skipped),
123	 *   sawNull: a null/undefined arm was declared }.
124	 * Under-detection is the designed failure direction: prose apostrophes and
125	 * stray closers suppress splitting/classification, never invent a union.
126	 */
127	function runtimeTypesOfNote(note) {
128	  if (!note || typeof note !== 'string') return { types: [], sawNull: false };
129	  const arms = [];
130	  let depth = 0, quote = null, cur = '';
131	  for (const ch of note) {
132	    if (quote) { cur += ch; if (ch === quote) quote = null; continue; }
133	    if (ch === "'" || ch === '"') { quote = ch; cur += ch; continue; }
134	    if (ch === '{' || ch === '[' || ch === '(') depth++;
135	    if ((ch === '}' || ch === ']' || ch === ')') && depth > 0) depth--;
136	    if (ch === '|' && depth === 0) { arms.push(cur.trim()); cur = ''; continue; }
137	    cur += ch;
138	  }
139	  arms.push(cur.trim());
140	  if (arms.length < 2) return { types: [], sawNull: false }; // not a union note — single-arm inference stays with typeOfNote
141	  const types = new Set();
142	  let sawNull = false;
143	  for (const arm of arms) {
144	    if (/^(null|undefined)$/.test(arm)) { sawNull = true; continue; }
145	    const t = runtimeTypeOfArm(arm);
146	    if (t) types.add(t);
147	  }
148	  return { types: [...types].sort(), sawNull };
149	}
150	
151	/**
152	 * Render the v2 `modelShape` declaration from stateKeys + initState (+ the
153	 * trace corpus when available). Types are inferred from the initState values;
154	 * a key whose initState value is null renders `nullable: true` with the type
155	 * taken from the stateKey's type note (default string).
156	 *
157	 * UNION KEYS (xstate field study, eval/FINDING-xstate-union-schema.md): a key
158	 * whose runtime type is a union — declared in the type note ("string |
159	 * {red: string}", the literal shape of xstate's state.value) or OBSERVED
160	 * across the captured windows' pre/post values — must render `{}` with no
161	 * `type` at all. The strict profile's checker validates single runtime types
162	 * only, so any single choice throws the moment the other arm is assigned;
163	 * rendering `type: '<init's type>'` here trapped every one of 5 independent
164	 * generations identically. The comment ships INTO the prompt so a generation
165	 * cannot "helpfully" tighten it back. Returns a JS object-literal snippet.
166	 */
167	export function renderModelShape(contract, windows = []) {
168	  const init = contract.initState || {};
169	  const entries = contract.stateKeys.map((k) => {
170	    const name = typeof k === 'string' ? k : k.name;
171	    const note = typeof k === 'string' ? '' : k.type;
172	    const value = init[name];
173	    // Distinct runtime types, strongest source first: real captured shapes
174	    // (windows' pre/post), then the init value, then the union-parsed note.
175	    // Nullability is tracked from ALL the same sources — the strict checker
176	    // tests null BEFORE type, so a union or window-observed null key rendered
177	    // without `nullable: true` would throw on every null write (the exact
178	    // all-generations trap class this renderer exists to close).
179	    const seen = new Set();
180	    let sawNull = Object.prototype.hasOwnProperty.call(init, name) && value === null;
181	    for (const w of windows) {
182	      for (const side of [w?.pre, w?.post]) {
183	        if (!side || !(name in side)) continue;
184	        if (side[name] === null) { sawNull = true; continue; }
185	        const t = typeOfValue(side[name]);
186	        if (t) seen.add(t);
187	      }
188	    }
189	    const initT = typeOfValue(value);
190	    if (initT) seen.add(initT);
191	    const noteTypes = runtimeTypesOfNote(note);
192	    if (noteTypes.sawNull) sawNull = true;
193	    // A union must be established WITHIN one source: real evidence
194	    // (windows + init) observing two runtime types, or the note ITSELF
195	    // declaring two pure type arms. Merging across sources would fabricate
196	    // unions from the common "container of enum: 'a' | 'b'" note shape —
197	    // the enum members are pure string LITERALS (values of the element
198	    // type), while init contributes the container type ('array'), and the
199	    // cross product read as array|string strips checking from a
200	    // single-runtime-type key.
201	    const isUnion = seen.size > 1 || noteTypes.types.length > 1;
202	    const nullable = sawNull ? ', nullable: true' : '';
203	    if (isUnion) {
204	      for (const t of noteTypes.types) seen.add(t);
205	      // sam-pattern ≥2.2 (#35): a type ARRAY declares the union outright —
206	      // shape checking stays live on every arm (the pre-2.2 escape was an
207	      // untyped `{}`, which gave up checking entirely).
208	      const arms = [...seen].sort();
209	      return `  ${name}: { type: [${arms.map((t) => `'${t}'`).join(', ')}]${nullable} },  // union — takes ${arms.join(' | ')}${sawNull ? ' | null' : ''} at runtime; keep the ARRAY exactly (collapsing it to one type makes the strict checker throw on the other arm)`;
210	    }
211	    // Single runtime type: real evidence (windows/init) beats the note; a
212	    // union-shaped note that classified to ONE pure type (an enum of string
213	    // literals) is next; the fuzzy whole-note keyword match is last.
214	    const type = (seen.size === 1 ? [...seen][0] : null)
215	      || (noteTypes.types.length === 1 ? noteTypes.types[0] : null)
216	      || typeOfNote(note) || 'string';
217	    return `  ${name}: { type: '${type}'${nullable} },`;
218	  });
219	  return `{\n${entries.join('\n')}\n}`;
220	}
221	
222	/**
223	 * Render per-intent payload schemas from actions[].dataFields. Field types are
224	 * inferred from contract.dataDomain values where declared, then from observed
225	 * trace windows (optional second argument), then from the dataFields type
226	 * note; default string. All declared fields are `required: true`.
227	 * Returns a JS object-literal snippet mapping ACTION -> schema.
228	 */
229	export function renderIntentSchemas(contract, windows = []) {
230	  const observed = {}; // action -> field -> first observed value
231	  for (const w of windows) {
232	    if (!w || typeof w.action !== 'string') continue;
233	    const bucket = (observed[w.action] = observed[w.action] || {});
234	    for (const [f, v] of Object.entries(w.data || {})) if (!(f in bucket)) bucket[f] = v;
235	  }
236	  const blocks = Object.entries(contract.actions).map(([name, spec]) => {
237	    const fields = dataFieldsOf(spec);
238	    const names = Object.keys(fields);
239	    if (!names.length) return `  ${name}: {},`;
240	    const body = names
241	      .map((f) => {
242	        const domainVals = contract.dataDomain?.[name]?.[f];
243	        const type =
244	          (Array.isArray(domainVals) && domainVals.length && typeOfValue(domainVals[0])) ||
245	          typeOfValue(observed[name]?.[f]) ||
246	          typeOfNote(fields[f]) ||
247	          'string';
248	        return `${f}: { type: '${type}', required: true }`;
249	      })
250	      .join(', ');
251	    return `  ${name}: { ${body} },`;
252	  });
253	  return `{\n${blocks.join('\n')}\n}`;
254	}
255	
256	/**
257	 * Render per-intent input domains from contract.dataDomain as lists of payload
258	 * objects (the cartesian product over the action's declared fields — the same
259	 * enumeration the checker explores). An action with no data fields gets the
260	 * single empty payload [{}]. An action WITH data fields but no complete
261	 * dataDomain is a hard error: in the v2 pipeline the domain is also the
262	 * exploration and transpilation domain, so a missing domain would silently
263	 * exclude the action (the exact failure class v2 exists to close).
264	 * Returns a JS object-literal snippet mapping ACTION -> [payload, ...].
265	 */
266	export function renderIntentDomains(contract) {
267	  const blocks = Object.entries(contract.actions).map(([name, spec]) => {
268	    const fields = Object.keys(dataFieldsOf(spec));
269	    if (!fields.length) return `  ${name}: [{}],`;
270	    const perField = fields.map((f) => {
271	      const vals = contract.dataDomain?.[name]?.[f];
272	      if (!Array.isArray(vals) || !vals.length) {
273	        throw new Error(
274	          `contract error: action '${name}' declares data field '${f}' but has no dataDomain.${name}.${f} — ` +
275	            `the v2 pipeline requires a finite domain for every data field (it drives generation, exploration, and transpilation). ` +
276	            `Add "dataDomain": { "${name}": { "${f}": [ ...representative values... ] } } to the contract.`
277	        );
278	      }
279	      return vals;
280	    });
281	    let combos = [{}];
282	    fields.forEach((f, i) => {
283	      const nxt = [];
284	      for (const c of combos) for (const v of perField[i]) nxt.push({ ...c, [f]: v });
285	      combos = nxt;
286	    });
287	    return `  ${name}: [${combos.map((c) => JSON.stringify(c)).join(', ')}],`;
288	  });
289	  return `{\n${blocks.join('\n')}\n}`;
290	}
291	
292	/**
293	 * Render specialRules as REQUIRED reject(reason) cases: each rule must be a
294	 * named rejection in the generated acceptor, so the replayer's rejection
295	 * column has a contract-anchored reason string to check.
296	 */
297	// windows: the trace corpus, when available. Field data (n8n study,
298	// eval/FINDING-n8n-reject-no-write.md) isolated the trigger for the 5/5
299	// reject-on-every-named-branch failure: generations reject ANY branch that
300	// maps to a named specialRules entry, independent of whether the rule
301	// describes a no-op — and this renderer used to COMMAND exactly that
302	// ("the acceptor MUST call reject(name)") for every rule. The corpus knows
303	// the truth: a rule whose matching windows all show post == pre (projection
304	// basis) is a genuine rejection; one whose windows show observable change
305	// names a BEHAVIORAL branch — the acceptor must perform the transition, and
306	// the name is only the why. Without a corpus (polygen's authoring path) the
307	// old must-reject reading is kept: there, specialRules are authored no-op
308	// declarations by construction.
309	export function renderSpecialRulesAsRejections(contract, windows = []) {
310	  const rules = contract.specialRules || [];
311	  if (!rules.length) {
312	    return (
313	      '  (none declared — still call reject(reason) for every action the\n' +
314	      '  implementation ignores in a given state; never fall through silently)'
315	    );
316	  }
317	  const primaryKey = contract.stateKeys && contract.stateKeys[0]
318	    ? (typeof contract.stateKeys[0] === 'string' ? contract.stateKeys[0] : contract.stateKeys[0].name)
319	    : null;
320	  // stable(): the SAME canonical equality the replayer and the
321	  // rejectedActedWindows detector use — raw JSON.stringify is key-order
322	  // sensitive and would let a rebuilt-object trace misclassify a rule.
323	  const changed = (w) => Object.keys(w.post || {}).some((k) => stable(w.pre?.[k]) !== stable(w.post[k]));
324	  // In-repo contracts write whenState in several idioms: a bare value, the
325	  // "<key> == VALUE" / "<key> == 'VALUE'" form, or the wildcard 'any'.
326	  // Normalize before matching so those rules classify from evidence instead
327	  // of silently falling into the decide-from-source bucket.
328	  const normState = (s) => String(s).replace(/^\s*[\w.]+\s*==\s*/, '').replace(/^['"]|['"]$/g, '').trim();
329	  const isWildcard = (s) => /^(any|\*)$/i.test(normState(s));
330	  return rules
331	    .map((r) => {
332	      const where = [r.whenState ? `the primary state is \`${r.whenState}\`` : null, r.whenAction ? `the action is \`${r.whenAction}\`` : null]
333	        .filter(Boolean)
334	        .join(' and ');
335	      const note = r.note ? ` ${r.note}` : '';
336	      // A rule with NEITHER whenState nor whenAction would match every
337	      // window — a name-only doc note must never become a blanket command
338	      // in either direction.
339	      if (!r.whenState && !r.whenAction) {
340	        return `  - **${r.name}** (name-only rule — documentation): decide reject-vs-transition per branch by the observable-change test; the name is a reason string, not an instruction.${note}`;
341	      }
342	      const matching = windows.filter((w) =>
343	        (!r.whenAction || w.action === r.whenAction)
344	        && (!r.whenState || isWildcard(r.whenState) || !primaryKey || String(w.pre?.[primaryKey]) === normState(r.whenState)));
345	      if (!windows.length || !matching.length) {
346	        // Unclassifiable (no corpus, or no window exercises the rule): the
347	        // authored-intent reading for polygen; a decide-from-source order for
348	        // the audit path where a corpus exists but never hits the rule.
349	        return windows.length
350	          ? `  - **${r.name}** (NOT exercised by any captured window): when ${where || 'this rule applies'}, decide from the SOURCE — call \`reject('${r.name}')\` ONLY if the code observably does nothing there; if the code acts, perform the transition and treat the name as documentation.${note}`
351	          : `  - **${r.name}**: when ${where || 'this rule applies'}, the acceptor MUST call \`reject('${r.name}')\` (do not fall through silently).${note}`;
352	      }
353	      const actedW = matching.filter(changed);
354	      const noopW = matching.filter((w) => !changed(w));
355	      if (actedW.length === 0) {
356	        return `  - **${r.name}** [REJECTION — every captured window here is a no-op]: when ${where || 'this rule applies'}, the acceptor MUST call \`reject('${r.name}')\` (do not fall through silently).${note}`;
357	      }
358	      if (noopW.length === 0) {
359	        return `  - **${r.name}** [BEHAVIORAL — the captured windows here CHANGE state (${actedW.length}/${matching.length})]: when ${where || 'this rule applies'}, the acceptor MUST perform the real transition via \`next.*\` writes and MUST NOT call reject() — this rule's name/note only documents WHY the transition looks the way it does.${note}`;
360	      }
361	      // MIXED rule: both arms exist in the corpus. Split by pre-state when
362	      // the arms are disjoint on the primary key (the common guard shape);
363	      // otherwise the branch is data-dependent and the instruction is the
364	      // decision TEST, never an absolute in either direction — an absolute
365	      // here would manufacture the inverse trap (act-instead-of-reject) on
366	      // one of the arms.
367	      const statesOf = (ws) => [...new Set(ws.map((w) => stable(w.pre?.[primaryKey])))];
368	      const actedStates = primaryKey ? statesOf(actedW) : [];
369	      const noopStates = primaryKey ? statesOf(noopW) : [];
370	      const disjoint = primaryKey && !actedStates.some((s) => noopStates.includes(s));
371	      if (disjoint) {
372	        const fmt = (arr) => arr.map((s) => `\`${JSON.parse(s)}\``).join(', ');
373	        return `  - **${r.name}** [MIXED — ${actedW.length}/${matching.length} captured windows change state]: when ${where || 'this rule applies'} — from ${primaryKey} ${fmt(actedStates)} the code TRANSITIONS (the acceptor MUST write \`next.*\`, MUST NOT reject); from ${primaryKey} ${fmt(noopStates)} the code does NOTHING (the acceptor MUST call \`reject('${r.name}')\`).${note}`;
374	      }
375	      return `  - **${r.name}** [MIXED, data-dependent — ${actedW.length}/${matching.length} captured windows change state]: when ${where || 'this rule applies'}, apply the observable-change test PER BRANCH: write \`next.*\` where the code acts, \`reject('${r.name}')\` where it observably does nothing — never one absolute for the whole rule.${note}`;
376	    })
377	    .join('\n');
378	}
