// SAM v2 strict-profile specification of src/host.impl.ts: the lease service, the two
// clients, and the network. The network is a bag of in-flight messages, kept as a
// sorted array of "Action|from|to|token" strings (token 0 when the message has none);
// `deliver` delivers one of them, so any delivery order is explored.
const { createInstance } = require('@cognitive-fab/sam-pattern');

const MAX_GRANTS = 2;
const MAX_WRITES = 2;
const CLIENTS = ['c0', 'c1'];

const INITIAL_STATE = {
  holder: null,
  token: 0,
  writes: 0,
  c0_status: 'idle', c0_token: 0, c0_writing: false, c0_revoked: 0,
  c1_status: 'idle', c1_token: 0, c1_writing: false, c1_revoked: 0,
  net: [],
};

const modelShape = {
  holder: { type: 'string', nullable: true },
  token: { type: 'number' },
  writes: { type: 'number' },
  c0_status: { type: 'string' },
  c0_token: { type: 'number' },
  c0_writing: { type: 'boolean' },
  c0_revoked: { type: 'number' },
  c1_status: { type: 'string' },
  c1_token: { type: 'number' },
  c1_writing: { type: 'boolean' },
  c1_revoked: { type: 'number' },
  net: { type: 'array' },
};

const msg = (action, from, to, token) => `${action}|${from}|${to}|${token}`;
const parse = (s) => {
  const [action, from, to, token] = s.split('|');
  return { action, from, to, token: Number(token) };
};
const add = (net, ...ms) => [...net, ...ms].sort();
const remove = (net, m) => {
  const i = net.indexOf(m);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};

const MESSAGES = [];
for (const c of CLIENTS) {
  MESSAGES.push(msg('Acquire', c, 'lease', 0));
  for (const t of [1, 2]) {
    MESSAGES.push(msg('Release', c, 'lease', t), msg('Write', c, 'lease', t));
    MESSAGES.push(msg('Granted', 'lease', c, t), msg('Revoked', 'lease', c, t));
  }
  for (const a of ['Denied', 'WriteDone', 'WriteRefused']) MESSAGES.push(msg(a, 'lease', c, 0));
}

const CLIENT_KEYS = ['status', 'token', 'writing', 'revoked'];
const SERVICE_KEYS = ['holder', 'token', 'writes'];
const allKeys = Object.keys(INITIAL_STATE);
const others = (...assigned) => allKeys.filter((k) => !assigned.includes(k));

const clientDomain = [{ client: 'c0' }, { client: 'c1' }, { client: 'cx' }];

const actions = {
  acquire: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  release: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  write: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  expire: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
  deliver: {
    action: (data = {}) => ({ ...data }),
    schema: { msg: { type: 'string', required: true } },
    domain: MESSAGES.map((m) => ({ msg: m })),
  },
};

const acceptors = {
  acquire: (model) => (p, { reject, next, unchanged }) => {
    const c = p.client;
    if (!CLIENTS.includes(c)) return reject('unknown-client');
    if (model[`${c}_status`] !== 'idle') return reject('not-idle');
    next[`${c}_status`] = 'requesting';
    next.net = add(model.net, msg('Acquire', c, 'lease', 0));
    unchanged(...others(`${c}_status`, 'net'));
  },
  release: (model) => (p, { reject, next, unchanged }) => {
    const c = p.client;
    if (!CLIENTS.includes(c)) return reject('unknown-client');
    if (model[`${c}_status`] !== 'holding') return reject('not-holding');
    next[`${c}_status`] = 'idle';
    next.net = add(model.net, msg('Release', c, 'lease', model[`${c}_token`]));
    unchanged(...others(`${c}_status`, 'net'));
  },
  write: (model) => (p, { reject, next, unchanged }) => {
    const c = p.client;
    if (!CLIENTS.includes(c)) return reject('unknown-client');
    if (model[`${c}_status`] !== 'holding') return reject('not-holding');
    if (model[`${c}_writing`]) return reject('write-pending');
    next[`${c}_writing`] = true;
    next.net = add(model.net, msg('Write', c, 'lease', model[`${c}_token`]));
    unchanged(...others(`${c}_writing`, 'net'));
  },
  expire: (model) => (p, { reject, next, unchanged }) => {
    if (model.holder === null) return reject('no-holder');
    next.holder = null;
    next.net = add(model.net, msg('Revoked', 'lease', model.holder, model.token));
    unchanged(...others('holder', 'net'));
  },
  deliver: (model) => (p, { reject, next, unchanged }) => {
    if (!model.net.includes(p.msg)) return reject('not-in-flight');
    const m = parse(p.msg);
    const rest = remove(model.net, p.msg);
    if (m.to === 'lease') {
      const from = m.from;
      if (m.action === 'Acquire') {
        if (model.holder === null && model.token < MAX_GRANTS) {
          const token = model.token + 1;
          next.holder = from;
          next.token = token;
          next.net = add(rest, msg('Granted', 'lease', from, token));
          return unchanged(...others('holder', 'token', 'net'));
        }
        next.net = add(rest, msg('Denied', 'lease', from, 0));
        return unchanged(...others('net'));
      }
      if (m.action === 'Release') {
        if (model.holder === from && m.token === model.token) {
          next.holder = null;
          next.net = rest;
          return unchanged(...others('holder', 'net'));
        }
        next.net = rest;
        return unchanged(...others('net'));
      }
      // Write
      if (model.holder === from && m.token === model.token && model.writes < MAX_WRITES) {
        next.writes = model.writes + 1;
        next.net = add(rest, msg('WriteDone', 'lease', from, 0));
        return unchanged(...others('writes', 'net'));
      }
      next.net = add(rest, msg('WriteRefused', 'lease', from, 0));
      return unchanged(...others('net'));
    }
    const c = m.to;
    const status = model[`${c}_status`];
    if (m.action === 'Granted') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
      next[`${c}_token`] = m.token;
      next[`${c}_status`] = m.token <= model[`${c}_revoked`] ? 'idle' : 'holding';
      return unchanged(...others('net', `${c}_token`, `${c}_status`));
    }
    if (m.action === 'Denied') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
      next[`${c}_status`] = 'idle';
      return unchanged(...others('net', `${c}_status`));
    }
    if (m.action === 'Revoked') {
      next.net = rest;
      if (status === 'holding') {
        if (m.token !== model[`${c}_token`]) return unchanged(...others('net'));
        next[`${c}_status`] = 'idle';
        return unchanged(...others('net', `${c}_status`));
      }
      if (m.token <= model[`${c}_revoked`]) return unchanged(...others('net'));
      next[`${c}_revoked`] = m.token;
      return unchanged(...others('net', `${c}_revoked`));
    }
    // WriteDone / WriteRefused
    next.net = rest;
    next[`${c}_writing`] = false;
    return unchanged(...others('net', `${c}_writing`));
  },
};

const instance = createInstance({ strict: true, hasAsyncActions: false });
const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

function init() { setState(INITIAL_STATE); }
function getState() { return instance({}).getState(); }
function setState(snapshot) { return instance({}).setState(snapshot); }

const exported = {};
for (const name of Object.keys(actions)) exported[name] = (data = {}) => intents[name](data);

module.exports = {
  instance, init, actions: exported, getState, setState,
  // helpers for the conformance test (not part of the SAM surface)
  INITIAL_STATE, MESSAGES, msg, CLIENT_KEYS, SERVICE_KEYS,
};

