  },
  deliver: (model) => (p, { reject, next, unchanged }) => {
    if (!model.net.includes(p.msg)) return reject('not-in-flight');
    const m = parse(p.msg);
    const rest = remove(model.net, p.msg);
    if (m.to === 'lease') {
      const from = m.from;
      if (m.action === 'Acquire') {
        if (model.holder === null && model.token < MAX_GRANTS) {
          const token = model.token + 1;
          next.holder = from;
          next.token = token;
          next.net = add(rest, msg('Granted', 'lease', from, token));
          return unchanged(...others('holder', 'token', 'net'));
        }
        next.net = add(rest, msg('Denied', 'lease', from, 0));
        return unchanged(...others('net'));
      }
      if (m.action === 'Release') {
        if (model.holder === from && m.token === model.token) {
          next.holder = null;
          next.net = rest;
          return unchanged(...others('holder', 'net'));
        }
        next.net = rest;
        return unchanged(...others('net'));
      }
      // Write
      if (model.holder === from && m.token === model.token && model.writes < MAX_WRITES) {
        next.writes = model.writes + 1;
        next.net = add(rest, msg('WriteDone', 'lease', from, 0));
        return unchanged(...others('writes', 'net'));
      }
      next.net = add(rest, msg('WriteRefused', 'lease', from, 0));
      return unchanged(...others('net'));
    }
    const c = m.to;
    const status = model[`${c}_status`];
    if (m.action === 'Granted') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
      next[`${c}_token`] = m.token;
      next[`${c}_status`] = m.token <= model[`${c}_revoked`] ? 'idle' : 'holding';
      return unchanged(...others('net', `${c}_token`, `${c}_status`));
    }
    if (m.action === 'Denied') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
      next[`${c}_status`] = 'idle';
      return unchanged(...others('net', `${c}_status`));
    }
    if (m.action === 'Revoked') {
      next.net = rest;
      if (status === 'holding') {
        if (m.token !== model[`${c}_token`]) return unchanged(...others('net'));
        next[`${c}_status`] = 'idle';
        return unchanged(...others('net', `${c}_status`));
      }
      if (m.token <= model[`${c}_revoked`]) return unchanged(...others('net'));
      next[`${c}_revoked`] = m.token;
      return unchanged(...others('net', `${c}_revoked`));
    }
    // WriteDone / WriteRefused
    next.net = rest;
    next[`${c}_writing`] = false;
    return unchanged(...others('net', `${c}_writing`));
  },
};

const instance = createInstance({ strict: true, hasAsyncActions: false });
const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

function init() { setState(INITIAL_STATE); }
function getState() { return instance({}).getState(); }
function setState(snapshot) { return instance({}).setState(snapshot); }

const exported = {};
for (const name of Object.keys(actions)) exported[name] = (data = {}) => intents[name](data);

module.exports = {
  instance, init, actions: exported, getState, setState,
  // helpers for the conformance test (not part of the SAM surface)
  INITIAL_STATE, MESSAGES, msg, CLIENT_KEYS, SERVICE_KEYS,
};

