import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const deliverWhere = async (h: Host, pred: (m: Message) => boolean) => {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
};

test('acquire, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.deepEqual(await h.client('c0'), { status: 'requesting', token: 0, writing: false });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: '' }, { id: '', from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } });
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual((await h.inFlight())[0].data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.deepEqual(await h.release('c0'), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
});

test('refusals and unknown clients', async () => {
  const h = await createHost();
  assert.equal((await h.acquire('c2')).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.expire()).ok, false);
  assert.equal(await h.client('lease'), null);
  await h.acquire('c0');
  assert.equal((await h.acquire('c0')).ok, false);
  assert.deepEqual(await h.inFlight().then((m) => m.length), 1);
});

test('denied while held, and only 2 grants', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.acquire('c1');
  await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'idle', token: 0, writing: false });
  await h.release('c0');
  await h.deliverAll();
  await h.acquire('c1');
  await h.deliverAll();
  assert.equal((await h.client('c1'))!.token, 2);
  await h.release('c1');
  await h.acquire('c0');
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('Revoked before Granted leaves the client idle', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await deliverWhere(h, (m) => m.action === 'Acquire');
  assert.deepEqual(await h.expire(), { ok: true });
  await deliverWhere(h, (m) => m.action === 'Revoked');
  assert.deepEqual(await h.client('c0'), { status: 'requesting', token: 0, writing: false });
  await deliverWhere(h, (m) => m.action === 'Granted');
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
});

test('a stale holder cannot write', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.expire();
  await h.acquire('c1');
  await deliverWhere(h, (m) => m.action === 'Acquire');
  await deliverWhere(h, (m) => m.action === 'Granted');
  // c0 still believes it holds token 1
  assert.equal((await h.client('c0'))!.status, 'holding');
  await h.write('c0');
  await deliverWhere(h, (m) => m.action === 'Write');
  const answer = (await h.inFlight()).find((m) => m.to === 'c0' && m.action.startsWith('Write'));
  assert.equal(answer!.action, 'WriteRefused');
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
});

test('at most 2 writes', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  for (let i = 0; i < 3; i++) { await h.write('c0'); await h.deliverAll(); }
  assert.equal((await h.lease()).writes, 2);
});

// Lockstep conformance: random command/delivery sequences drive the implementation and
// the polygraph spec together; their states must agree after every step.
const require = createRequire(import.meta.url);
const spec = require('../spec/lease.spec.cjs');

async function implState(h: Host) {
  const lease = await h.lease();
  const s: Record<string, unknown> = { holder: lease.holder, token: lease.token, writes: lease.writes };
  for (const c of ['c0', 'c1']) {
    const v = (await h.client(c))!;
    s[`${c}_status`] = v.status; s[`${c}_token`] = v.token; s[`${c}_writing`] = v.writing;
  }
  s.net = (await h.inFlight()).map((m) => spec.msg(m.action, m.from, m.to, (m.data.token as number) ?? 0)).sort();
  return s;
}
function specState() {
  const s = { ...spec.getState() };
  delete s.c0_revoked; delete s.c1_revoked;
  return s;
}

test('implementation conforms to the spec on random runs', async () => {
  let seed = 12345;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 400; run++) {
    const h = await createHost();
    spec.init();
    for (let step = 0; step < 40; step++) {
      const kind = rnd(5);
      const client = ['c0', 'c1', 'cx'][rnd(3)];
      if (kind === 4) {
        const msgs = await h.inFlight();
        if (!msgs.length) continue;
        const m = msgs[rnd(msgs.length)];
        await h.deliver(m.id);
        spec.actions.deliver({ msg: spec.msg(m.action, m.from, m.to, (m.data.token as number) ?? 0) });
      } else {
        const name = (['acquire', 'release', 'write', 'expire'] as const)[kind];
        const before = specState();
        const out = name === 'expire' ? await h.expire() : await h[name](client);
        spec.actions[name](name === 'expire' ? {} : { client });
        assert.equal(out.ok, JSON.stringify(before) !== JSON.stringify(specState()), `${name}(${client}) outcome`);
      }
      assert.deepEqual(await implState(h), specState(), `run ${run} step ${step}`);
    }
  }
});

