// Negative control: lease.spec.cjs with clients that forget the revoked token, so a
// Granted arriving after its Revoked makes the client hold an already-expired lease.
// The checker must report the quiescence invariant violated on this module.
const { readFileSync } = require('node:fs');
const { join } = require('node:path');

const source = readFileSync(join(__dirname, '..', 'lease.spec.cjs'), 'utf8');
const mutated = source.replace("m.token <= model[`${c}_revoked`] ? 'idle' : 'holding'", "'holding'");
