      if (status === 'releasing') return unchanged(...others('net'));
      if (status === 'holding') {
        if (m.token !== model[`${c}_token`]) return unchanged(...others('net'));
        next[`${c}_status`] = 'idle';
        return unchanged(...others('net', `${c}_status`));
      }
      if (m.token <= model[`${c}_revoked`]) return unchanged(...others('net'));
      next[`${c}_revoked`] = m.token;
      return unchanged(...others('net', `${c}_revoked`));
    }
    // WriteDone / WriteRefused
    next.net = rest;
    next[`${c}_writing`] = false;
    return unchanged(...others('net', `${c}_writing`));
  },
};

const instance = createInstance({ strict: true, hasAsyncActions: false });
const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

function init() { setState(INITIAL_STATE); }
function getState() { return instance({}).getState(); }
function setState(snapshot) { return instance({}).setState(snapshot); }

const exported = {};
for (const name of Object.keys(actions)) exported[name] = (data = {}) => intents[name](data);

module.exports = {
  instance, init, actions: exported, getState, setState,
  // helpers for the conformance test (not part of the SAM surface)
  INITIAL_STATE, MESSAGES, msg, CLIENT_KEYS, SERVICE_KEYS,
};

