2	import assert from 'node:assert/strict';
3	import createHost from '../src/host.impl.ts';
4	import type { Host, Message } from '../host.ts';
5	
6	const deliverWhere = async (h: Host, pred: (m: Message) => boolean) => {
7	  const m = (await h.inFlight()).find(pred);
8	  assert.ok(m, 'expected message in flight');
9	  await h.deliver(m.id);
10	};
11	
12	test('acquire, write, release', async () => {
13	  const h = await createHost();
14	  assert.deepEqual(await h.acquire('c0'), { ok: true });
15	  assert.deepEqual(await h.client('c0'), { status: 'requesting', token: 0, writing: false });
16	  const msgs = await h.inFlight();
17	  assert.equal(msgs.length, 1);
18	  assert.deepEqual({ ...msgs[0], id: '' }, { id: '', from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } });
19	  await h.deliverAll();
20	  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
21	  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
22	  assert.deepEqual(await h.write('c0'), { ok: true });
23	  assert.equal((await h.write('c0')).ok, false);
24	  assert.deepEqual((await h.inFlight())[0].data, { from: 'c0', token: 1 });
25	  await h.deliverAll();
26	  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
27	  assert.deepEqual(await h.release('c0'), { ok: true });
28	  await h.deliverAll();
29	  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
30	  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
31	});
32	
33	test('refusals and unknown clients', async () => {
34	  const h = await createHost();
35	  assert.equal((await h.acquire('c2')).ok, false);
36	  assert.equal((await h.release('c0')).ok, false);
37	  assert.equal((await h.write('c0')).ok, false);
38	  assert.equal((await h.expire()).ok, false);
39	  assert.equal(await h.client('lease'), null);
40	  await h.acquire('c0');
41	  assert.equal((await h.acquire('c0')).ok, false);
42	  assert.deepEqual(await h.inFlight().then((m) => m.length), 1);
43	});
44	
45	test('denied while held, and only 2 grants', async () => {
46	  const h = await createHost();
47	  await h.acquire('c0');
48	  await h.deliverAll();
49	  await h.acquire('c1');
50	  await h.deliverAll();
51	  assert.deepEqual(await h.client('c1'), { status: 'idle', token: 0, writing: false });
52	  await h.release('c0');
53	  await h.deliverAll();
54	  await h.acquire('c1');
55	  await h.deliverAll();
56	  assert.equal((await h.client('c1'))!.token, 2);
57	  await h.release('c1');
58	  await h.acquire('c0');
59	  await h.deliverAll();
60	  assert.equal((await h.client('c0'))!.status, 'idle');
61	  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
62	});
63	
64	test('Revoked before Granted leaves the client idle', async () => {
65	  const h = await createHost();
66	  await h.acquire('c0');
67	  await deliverWhere(h, (m) => m.action === 'Acquire');
68	  assert.deepEqual(await h.expire(), { ok: true });
69	  await deliverWhere(h, (m) => m.action === 'Revoked');
70	  assert.deepEqual(await h.client('c0'), { status: 'requesting', token: 0, writing: false });
71	  await deliverWhere(h, (m) => m.action === 'Granted');
72	  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
73	  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
74	});
75	
76	test('a stale holder cannot write', async () => {
77	  const h = await createHost();
78	  await h.acquire('c0');
79	  await h.deliverAll();
80	  await h.expire();
81	  await h.acquire('c1');
82	  await deliverWhere(h, (m) => m.action === 'Acquire');
83	  await deliverWhere(h, (m) => m.action === 'Granted');
84	  // c0 still believes it holds token 1
