  holder: null,
  token: 0,
  writes: 0,
  wrote: false, // a write was taken since the last grant
  c0_status: 'idle', c0_token: 0, c0_writing: false, c0_revoked: 0,
  c1_status: 'idle', c1_token: 0, c1_writing: false, c1_revoked: 0,
  net: [],
};

const modelShape = {
  holder: { type: 'string', nullable: true },
  token: { type: 'number' },
  writes: { type: 'number' },
  wrote: { type: 'boolean' },
  c0_status: { type: 'string' },
  c0_token: { type: 'number' },
  c0_writing: { type: 'boolean' },
  c0_revoked: { type: 'number' },
  c1_status: { type: 'string' },
  c1_token: { type: 'number' },
  c1_writing: { type: 'boolean' },
  c1_revoked: { type: 'number' },
  net: { type: 'array' },
};

