const SERVICE_KEYS = ['holder', 'token', 'writes', 'wrote'];
const allKeys = Object.keys(INITIAL_STATE);
const others = (...assigned) => allKeys.filter((k) => !assigned.includes(k));

const clientDomain = [{ client: 'c0' }, { client: 'c1' }, { client: 'cx' }];

const actions = {
  acquire: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  release: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  write: { action: (data = {}) => ({ ...data }), schema: { client: { type: 'string', required: true } }, domain: clientDomain },
  expire: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
  deliver: {
    action: (data = {}) => ({ ...data }),
