  write: (model) => (p, { reject, next, unchanged }) => {
    const c = p.client;
    if (!CLIENTS.includes(c)) return reject('unknown-client');
    if (model[`${c}_status`] !== 'holding') return reject('not-holding');
    if (model[`${c}_writing`]) return reject('write-pending');
    next[`${c}_writing`] = true;
