    const status = model[`${c}_status`];
    if (m.action === 'Granted') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
      next[`${c}_token`] = m.token;
      next[`${c}_status`] = m.token <= model[`${c}_revoked`] ? 'idle' : 'holding';
      return unchanged(...others('net', `${c}_token`, `${c}_status`));
    }
    if (m.action === 'Denied') {
      next.net = rest;
      if (status !== 'requesting') return unchanged(...others('net'));
