// The rules the brief requires, over the state of spec/lease.spec.cjs.
const CLIENTS = ['c0', 'c1'];
const parse = (s) => {
  const [action, from, to, token] = s.split('|');
  return { action, from, to, token: Number(token) };
};

export const stateInvariants = [
  {
    name: 'at most one client holds the lease with the current token',
    pred: (s) => CLIENTS.filter((c) => s[`${c}_status`] === 'holding' && s[`${c}_token`] === s.token).length <= 1,
  },
  {
    name: 'once no message is in transit, a client holds the lease exactly when the service says it does',
    pred: (s) =>
      s.net.length > 0 ||
      CLIENTS.every((c) => (s[`${c}_status`] === 'holding') === (s.holder === c) &&
        (s.holder !== c || s[`${c}_token`] === s.token)),
  },
  { name: 'at most 2 leases granted', pred: (s) => s.token >= 0 && s.token <= 2 },
  { name: 'at most 2 writes taken', pred: (s) => s.writes >= 0 && s.writes <= 2 },
  { name: 'at most one write per grant: writes never exceed grants', pred: (s) => s.writes <= s.token },
  {
    name: 'a client is writing exactly when its write or its answer is in transit',
    pred: (s) =>
      CLIENTS.every((c) => {
        const pending = s.net.map(parse).filter((m) =>
          (m.action === 'Write' && m.from === c) ||
          ((m.action === 'WriteDone' || m.action === 'WriteRefused') && m.to === c)).length;
        return pending === (s[`${c}_writing`] ? 1 : 0);
      }),
  },
  {
    name: 'a client is releasing exactly when its release or its acknowledgement is in transit',
    pred: (s) =>
      CLIENTS.every((c) => {
        const pending = s.net.map(parse).filter((m) =>
          (m.action === 'Release' && m.from === c) || (m.action === 'Released' && m.to === c)).length;
        return pending === (s[`${c}_status`] === 'releasing' ? 1 : 0);
      }),
  },
  {
    name: 'once a release is acknowledged, the service no longer has the client as holder',
    pred: (s) => CLIENTS.every((c) => !s.net.includes(`Released|lease|${c}|0`) || s.holder !== c),
  },
  {
    name: 'a client never holds a token newer than the last granted',
    pred: (s) => CLIENTS.every((c) => s[`${c}_token`] <= s.token),
  },
];

export const transitionInvariants = [
  {
    name: 'the service takes a write only from the holder with the current token',
    pred: (pre, action, data, post) => {
      if (post.writes === pre.writes) return true;
      if (post.writes !== pre.writes + 1 || action !== 'deliver') return false;
      const m = parse(data.msg);
      return m.action === 'Write' && m.from === pre.holder && m.token === pre.token;
    },
  },
  {
    name: 'the service takes at most one write per grant',
    pred: (pre, action, data, post) => post.writes === pre.writes || !pre.wrote,
  },
  {
    name: 'a grant starts with no write taken',
    pred: (pre, action, data, post) => post.token === pre.token || post.wrote === false,
  },
  {
    name: 'tokens only go up, by one per grant',
    pred: (pre, action, data, post) => post.token === pre.token || post.token === pre.token + 1,
  },
];

